import { createRequire } from "node:module";
const require = createRequire(import.meta.url);
const M = require("../../exercise-metrics.js");
const defs = ['loadKg','reps'].map(s => M.DEFINITIONS.find(d => d.semantic === s));
const prescription = {id:'slot-a:c1:s1',slotId:'slot-a',cycleIndex:1,setIndex:1,exerciseId:'exercise-a',metricType:'source_metrics@1',metricIds:defs.map(d=>d.id),metricDefinitions:defs,targets:{reps:{min:7,max:9}},rir:1,status:'ready',loadingModel:{bodyweightCoefficient:0}};
const context = {bySlotId:{'slot-a':{equipmentId:'rack-a',loadingConvention:'external',bodyweightContributionEnabled:false,externalLoadMultiplier:1,availableLoadsKg:Array.from({length:61},(_,i)=>i*2.5)}}};
const row = (loadKg=100, setIndex=0, extra={})=>({exerciseId:'exercise-a',completed:true,setIndex,rir:2,effortSource:'rir',equipmentId:'rack-a',loadingConvention:'external',loadingContext:{loadingConvention:'external',bodyweightCoefficient:0,bodyweightContributionEnabled:false,externalLoadMultiplier:1},metricIds:defs.map(d=>d.id),metricValues:[{metricId:defs[0].id,value:loadKg,unit:'kg'},{metricId:defs[1].id,value:8,unit:'reps'}],...extra});
const session = (id, loads=[100,95,90], date='2026-11-09', extra={})=>({sessionId:id,date,completed:true,sets:loads.map((load,i)=>row(load,i,extra))});
const solid = ()=>Array.from({length:4},(_,i)=>session('s'+i));
export const cases=[];
function add(name, history=[], options={}) {const input=[[{...prescription,...options.prescription}],history,options.live||[],options.context||context,{now:'2026-11-09',...options.settings}];cases.push({name,input,});}
add('no-history');
add('one-session-ten-days',[session('s1',undefined,'2026-10-30')]);
add('four-sessions',solid());
add('three-on-target-checks',solid(),{settings:{calibration:{version:"calibration@077.1",delta:0,n:3,spread:0,state:'calibrated',reason:null}}});
add('four-of-nine-pairs',[session('a',[100,95,120,110]),session('b',[100,120,110,130]),session('c',[100,120,110,130])]);
add('fifty-day-break',Array.from({length:4},(_,i)=>session('s'+i,undefined,'2026-09-20')));
add('six-sets-two-sessions',[session('a'),session('b')]);
add('below-six-sets',[session('a'),session('b',[100,95])]);
add('six-sets-one-session',[session('a',[100,95,90,85,80,75])]);
add('agreement-at-point-six',[session('a',[100,90,110,100,120,110]),session('b',[100])]);
add('three-disagreeing-pairs',[session('a',[100,120,140,100]),session('b',[100,100,100])]);
add('four-disagreeing-pairs',[session('a',[100,120,140,100,130]),session('b',[100,100])]);
add('forty-one-day-gap',Array.from({length:4},(_,i)=>session('s'+i,undefined,'2026-09-29')));
add('forty-two-day-gap',Array.from({length:4},(_,i)=>session('s'+i,undefined,'2026-09-28')));
for(const source of ['rir','reps_left','effort','reps_left_3plus','reps_left_5plus',null,'prefilled','unsure','failure']) add('quality-'+source,solid().map(s=>({...s,sets:s.sets.map(r=>({...r,effortSource:source}))})));
add('missing-date',solid().map(({date,...s})=>s));
add('warmup',solid().map(s=>({...s,sets:s.sets.map(r=>({...r,warmup:true}))})));
add('ninety-day-decay',[session('a',undefined,'2026-08-11'),session('b',undefined,'2026-08-11')]);
add('identical-pairs',[session('a',[100,100,100]),session('b',[100,100,100])]);
add('inconsistent-checks',solid(),{settings:{calibration:{version:"calibration@077.1",delta:0,n:4,spread:3,state:'uncalibrated',reason:'inconsistent'}}});
add('foreign-calibration',solid(),{settings:{calibration:{version:'calibration@future',delta:0,n:4,spread:3,state:'uncalibrated',reason:'inconsistent'}}});
add('live-only',[],{prescription:{setIndex:2},live:[row()]});
add('configuration-required',solid(),{context:{}});
add('invalid',solid(),{prescription:{metricType:'invalid'}});
for(const delta of [-1,1,2]) add('bounded-shift-'+delta,solid(),{settings:{calibration:{version:"calibration@077.1",delta,n:4,spread:1,state:delta<0?'under':'over',reason:null}}});
add('wrong-equipment',solid().map(s=>({...s,sets:s.sets.map(r=>({...r,equipmentId:'other'}))})));
add('missing-rir',solid().map(s=>({...s,sets:s.sets.map(r=>({...r,rir:null}))})));
add('missing-source',solid().map(s=>({...s,sets:s.sets.map(({effortSource,...r})=>r)})));
add('undated-pair-endpoint',[session('a',[100,95,90],null),session('b',[100,95,90])]);
cases.at(-1).input[1][0].sets[1].date = '2026-11-09';
